  rows.length
    ? `<table><thead><tr>${heads.map((h) => `<th scope="col">${esc(h)}</th>`).join("")}</tr></thead><tbody>${rows.map((row) => `<tr>${row.map((cell) => `<td>${esc(String(cell))}</td>`).join("")}</tr>`).join("")}</tbody></table>`
    : `<p class="section-description">${esc(empty)}</p>`;
